<?php
require_once __DIR__ . '/_layout.php';
requirePermission('vehicles.view');
$agencyIds=currentAgencyIds();

if(requestMethod()==='POST'){
    requirePermission('vehicles.manage'); requireCsrfPost(); $action=$_POST['action']??'';
    try{
        if($action==='create'){
            $agencyId=(int)($_POST['agency_id']??0);requireAgencyAccess($agencyId);$categoryId=(int)($_POST['category_id']??0);
            $category=dbFetchOne('SELECT id FROM vehicle_categories WHERE id=:id AND (agency_id=:agency OR agency_id IS NULL) AND archived_at IS NULL',['id'=>$categoryId,'agency'=>$agencyId]);if(!$category)throw new InvalidArgumentException('Select a valid vehicle category.');
            $registration=strtoupper(trim((string)($_POST['registration_number']??'')));$brand=trim((string)($_POST['brand']??''));$model=trim((string)($_POST['model']??''));$price=positiveMoney($_POST['base_daily_price']??'');
            if($registration===''||$brand===''||$model===''||$price===null)throw new InvalidArgumentException('Registration, brand, model, and a valid daily price are required.');
            $imagePath=null;if(isset($_FILES['image'])&&($_FILES['image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$stored=storeValidatedImage($_FILES['image'],'vehicles');$imagePath=$stored['path'];}
            dbExecute('INSERT INTO vehicles (agency_id,category_id,registration_number,vin,brand,model,version,model_year,colour,fuel,transmission,seats,doors,luggage_capacity,current_mileage,purchase_date,purchase_price,financing_type,monthly_finance_amount,base_daily_price,recommended_deposit,mileage_allowance,status,primary_image_path,created_by,updated_by) VALUES (:agency,:category,:registration,:vin,:brand,:model,:version,:year,:colour,:fuel,:transmission,:seats,:doors,:luggage,:mileage,:purchase_date,:purchase_price,:financing,:finance_amount,:daily_price,:deposit,:allowance,:status,:image,:user,:user)',[
                'agency'=>$agencyId,'category'=>$categoryId,'registration'=>$registration,'vin'=>trim((string)($_POST['vin']??''))?:null,'brand'=>$brand,'model'=>$model,'version'=>trim((string)($_POST['version']??'')),'year'=>($_POST['model_year']??'')!==''?(int)$_POST['model_year']:null,'colour'=>trim((string)($_POST['colour']??'')),'fuel'=>validateChoice($_POST['fuel']??'', ['petrol','diesel','hybrid','electric','other'],null),'transmission'=>validateChoice($_POST['transmission']??'', ['manual','automatic'],'manual'),'seats'=>(int)($_POST['seats']??0)?:null,'doors'=>(int)($_POST['doors']??0)?:null,'luggage'=>(int)($_POST['luggage_capacity']??0)?:null,'mileage'=>max(0,(int)($_POST['current_mileage']??0)),'purchase_date'=>($_POST['purchase_date']??'')?:null,'purchase_price'=>positiveMoney($_POST['purchase_price']??'')?:null,'financing'=>validateChoice($_POST['financing_type']??'', ['owned','loan','lease'],null),'finance_amount'=>positiveMoney($_POST['monthly_finance_amount']??'')?:null,'daily_price'=>$price,'deposit'=>positiveMoney($_POST['recommended_deposit']??'0')??'0.00','allowance'=>max(0,(int)($_POST['mileage_allowance']??0))?:null,'status'=>'available','image'=>$imagePath,'user'=>currentUserId()
            ]);$id=(int)db()->lastInsertId();dbExecute('INSERT INTO vehicle_status_history(vehicle_id,to_status,reason,changed_by)VALUES(:id,\'available\',\'Vehicle created\',:user)',['id'=>$id,'user'=>currentUserId()]);auditLog('vehicle.created','vehicle',$id,null,['registration'=>$registration],$agencyId);flash('success','Vehicle created.');
        }elseif($action==='status'){
            $id=(int)($_POST['id']??0);$vehicle=dbFetchOne('SELECT * FROM vehicles WHERE id=:id FOR UPDATE',['id'=>$id]);if(!$vehicle)throw new InvalidArgumentException('Vehicle not found.');requireAgencyAccess($vehicle['agency_id']);$status=validateChoice($_POST['status']??'',vehicleStatuses(),null);if(!$status)throw new InvalidArgumentException('Invalid vehicle status.');
            dbExecute('UPDATE vehicles SET status=:status,updated_by=:user WHERE id=:id',['status'=>$status,'user'=>currentUserId(),'id'=>$id]);dbExecute('INSERT INTO vehicle_status_history(vehicle_id,from_status,to_status,reason,changed_by)VALUES(:id,:old,:new,:reason,:user)',['id'=>$id,'old'=>$vehicle['status'],'new'=>$status,'reason'=>trim((string)($_POST['reason']??'')),'user'=>currentUserId()]);auditLog('vehicle.status_changed','vehicle',$id,['status'=>$vehicle['status']],['status'=>$status],$vehicle['agency_id']);flash('success','Vehicle status updated.');
        }elseif($action==='archive'){
            $id=(int)($_POST['id']??0);$vehicle=dbFetchOne('SELECT * FROM vehicles WHERE id=:id',['id'=>$id]);if(!$vehicle)throw new InvalidArgumentException('Vehicle not found.');requireAgencyAccess($vehicle['agency_id']);$history=dbFetchOne('SELECT id FROM reservations WHERE vehicle_id=:id LIMIT 1',['id'=>$id]);dbExecute('UPDATE vehicles SET archived_at=NOW(),status=:status,updated_by=:user WHERE id=:id',['status'=>$history?'retired':'retired','user'=>currentUserId(),'id'=>$id]);auditLog('vehicle.archived','vehicle',$id,$vehicle,['status'=>'retired'],$vehicle['agency_id']);flash('success','Vehicle archived; historical records were preserved.');
        }
    }catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Vehicle operation failed');flash('danger','The vehicle operation could not be completed.');}safeRedirect('vehicles.php');
}

[$page,$size,$offset]=paginationParameters();$agencyId=(int)($_GET['agency_id']??($agencyIds[0]??0));requireAgencyAccess($agencyId);$status=trim((string)($_GET['status']??''));$where='v.agency_id=:agency AND v.archived_at IS NULL';$params=['agency'=>$agencyId];if(in_array($status,vehicleStatuses(),true)){$where.=' AND v.status=:status';$params['status']=$status;}
$vehicles=dbFetchAll("SELECT v.*,c.name category_name FROM vehicles v JOIN vehicle_categories c ON c.id=v.category_id WHERE $where ORDER BY v.registration_number LIMIT $size OFFSET $offset",$params);$agencies=dbFetchAll('SELECT id,name FROM agencies WHERE archived_at IS NULL ORDER BY name');$categories=dbFetchAll('SELECT id,name,agency_id FROM vehicle_categories WHERE archived_at IS NULL ORDER BY name');
backofficeHeader(t('vehicles'),'vehicles.php');?><div class="page-head"><h1><?=e(t('vehicles'))?></h1></div><form class="filters"><label>Agency<select name="agency_id"><?php foreach($agencies as $agency):if(currentUserRole()!==ROLE_OWNER&&!in_array((int)$agency['id'],$agencyIds,true))continue;?><option value="<?=e($agency['id'])?>" <?=$agencyId==(int)$agency['id']?'selected':''?>><?=e($agency['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All</option><?php foreach(vehicleStatuses() as $item):?><option <?=$status===$item?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></label><button class="btn secondary">Filter</button></form>
<div class="grid"><?php if(can('vehicles.manage')):?><section class="card"><h2>New vehicle</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="create"><div class="grid"><label>Agency<select name="agency_id" required><?php foreach($agencies as $agency):if(currentUserRole()!==ROLE_OWNER&&!in_array((int)$agency['id'],$agencyIds,true))continue;?><option value="<?=e($agency['id'])?>"><?=e($agency['name'])?></option><?php endforeach;?></select></label><label>Category<select name="category_id" required><?php foreach($categories as $category):?><option value="<?=e($category['id'])?>"><?=e($category['name'])?></option><?php endforeach;?></select></label><label>Registration<input name="registration_number" required></label><label>VIN<input name="vin"></label><label>Brand<input name="brand" required></label><label>Model<input name="model" required></label><label>Version<input name="version"></label><label>Year<input type="number" name="model_year" min="1900" max="2100"></label><label>Colour<input name="colour"></label><label>Fuel<select name="fuel"><option>petrol</option><option>diesel</option><option>hybrid</option><option>electric</option><option>other</option></select></label><label>Transmission<select name="transmission"><option>manual</option><option>automatic</option></select></label><label>Seats<input type="number" name="seats" min="1" max="99"></label><label>Doors<input type="number" name="doors" min="1" max="10"></label><label>Luggage<input type="number" name="luggage_capacity" min="0" max="99"></label><label>Mileage<input type="number" name="current_mileage" min="0"></label><label>Daily price<input name="base_daily_price" inputmode="decimal" required></label><label>Deposit<input name="recommended_deposit" inputmode="decimal"></label><label class="full">Vehicle image (JPEG, PNG, WebP; max <?=e(appConfig('upload_max_bytes'))?> bytes)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label></div><button class="btn primary"><?=e(t('save'))?></button></form></section><?php endif;?><section class="card"><h2>Fleet</h2><div class="table-wrap"><table><tr><th>Registration</th><th>Vehicle</th><th>Category</th><th>Price/day</th><th>Status</th><th><?=e(t('actions'))?></th></tr><?php foreach($vehicles as $vehicle):?><tr><td><?=e($vehicle['registration_number'])?></td><td><?=e($vehicle['brand'].' '.$vehicle['model'])?></td><td><?=e($vehicle['category_name'])?></td><td><?=money($vehicle['base_daily_price'])?></td><td><?=statusBadge($vehicle['status'])?></td><td><?php if(can('vehicles.manage')):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=e($vehicle['id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(vehicleStatuses() as $item):?><option <?=$item===$vehicle['status']?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></form><form method="post" onsubmit="return confirm('Archive this vehicle?')"><?=csrfField()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=e($vehicle['id'])?>"><button class="btn danger">Archive</button></form><?php endif;?></td></tr><?php endforeach;?></table><?php if(!$vehicles):?><p class="empty"><?=e(t('no_results'))?></p><?php endif;?></div></section></div><?php backofficeFooter();
